// ## Internal data
interface GameDynamo {
    game_id: string          // uuid
    user_id: string          // uuid
    puzzle_id: string        // uuid
    puzzle_date_iso_day: string  // YYYY-MM-DD
    moves: GuessGraded[]     // 1-6 guesses
    moves_qty: number        // count of guesses
    completed_at_millis: number
    won: boolean
}

interface Puzzle {
    puzzle_id: string        // uuid even though cant we just use the date? Do we really need this?
    word: string
    date_iso_day: string     // date formatted like YYYY-MM-DD
}